import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/commands.md","filePath":"en/modules/kits/commands.md","lastUpdated":0}`),a={name:`en/modules/kits/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h1><p>The main command is <code>/emakikits</code>, with aliases <code>/emakikit</code> and <code>/ekits</code>. Every subcommand checks <code>emakikits.use</code> first, then the permission for that subcommand</p><h2 id="player-commands" tabindex="-1">Player commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to “Player commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th><th>Permission</th></tr></thead><tbody><tr><td><code>/emakikits help</code></td><td>List available subcommands</td><td><code>emakikits.use</code></td></tr><tr><td><code>/emakikits list</code></td><td>List loaded kits (type, id, display name, enabled)</td><td><code>emakikits.use</code></td></tr><tr><td><code>/emakikits claim &lt;kitId&gt;</code></td><td>Claim a kit</td><td><code>emakikits.claim</code></td></tr><tr><td><code>/emakikits choose &lt;kitId&gt; [option...]</code></td><td>Open the choice GUI with no options; submit directly with option ids</td><td><code>emakikits.open</code></td></tr><tr><td><code>/emakikits buy &lt;kitId&gt;</code></td><td>Buy one claimable use (debited through the CoreLib economy bridge)</td><td><code>emakikits.buy</code></td></tr><tr><td><code>/emakikits redeem &lt;kitId&gt; &lt;code&gt;</code></td><td>Redeem a CDK kit</td><td><code>emakikits.redeem</code></td></tr><tr><td><code>/emakikits invite &lt;player&gt;</code></td><td>Bind an invite relationship (the invitee must be online)</td><td><code>emakikits.invite</code></td></tr><tr><td><code>/emakikits open &lt;kitId&gt;</code></td><td>Claim a kit, equivalent to <code>claim</code></td><td><code>emakikits.open</code></td></tr></tbody></table><h2 id="admin-commands" tabindex="-1">Admin commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to “Admin commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th><th>Permission</th></tr></thead><tbody><tr><td><code>/emakikits inspect &lt;player&gt;</code></td><td>Show the player&#39;s audit record count and details</td><td><code>emakikits.inspect</code></td></tr><tr><td><code>/emakikits grant &lt;player&gt; &lt;kitId&gt;</code></td><td>Grant one claimable use to a player</td><td><code>emakikits.grant</code></td></tr><tr><td><code>/emakikits cdk list</code></td><td>List CDK kits and their code counts</td><td><code>emakikits.cdk</code></td></tr><tr><td><code>/emakikits cdk disable &lt;code&gt;</code></td><td>Disable a code</td><td><code>emakikits.cdk</code></td></tr><tr><td><code>/emakikits reload</code></td><td>Reload <code>config.yml</code>, <code>kits/*.yml</code>, lang, and GUI templates; re-register cron windows</td><td><code>emakikits.reload</code></td></tr></tbody></table><h2 id="permission-table" tabindex="-1">Permission table <a class="header-anchor" href="#permission-table" aria-label="Permalink to “Permission table”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>emakikits.use</code></td><td><code>true</code></td><td>Root permission for player commands</td></tr><tr><td><code>emakikits.claim</code></td><td><code>true</code></td><td>Claim kits</td></tr><tr><td><code>emakikits.open</code></td><td><code>true</code></td><td>Open the choice GUI / claim a purchased kit</td></tr><tr><td><code>emakikits.buy</code></td><td><code>true</code></td><td>Buy kits</td></tr><tr><td><code>emakikits.redeem</code></td><td><code>true</code></td><td>Redeem CDK codes</td></tr><tr><td><code>emakikits.invite</code></td><td><code>true</code></td><td>Bind invite relationships</td></tr><tr><td><code>emakikits.admin</code></td><td><code>op</code></td><td>Admin parent node, including the child permissions below</td></tr><tr><td><code>emakikits.reload</code> / <code>grant</code> / <code>inspect</code> / <code>cdk</code></td><td><code>op</code></td><td>Reload, grant, inspect, and CDK management respectively</td></tr></tbody></table><h2 id="tab-completion" tabindex="-1">Tab completion <a class="header-anchor" href="#tab-completion" aria-label="Permalink to “Tab completion”">​</a></h2><p>Top-level subcommands (<code>help</code>, <code>list</code>, <code>claim</code>, <code>choose</code>, <code>buy</code>, <code>redeem</code>, <code>invite</code>, <code>open</code>, <code>inspect</code>, <code>grant</code>, <code>cdk</code>, <code>reload</code>) and the second argument of subcommands that need a kit id (the id set from <code>kits/*.yml</code>) are completed</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>CDK kits cannot be claimed with <code>claim</code>; use <code>redeem</code>. Invite kits are bound through the join invite-code flow, not <code>claim</code></li><li><code>choose</code> with option ids validates the count against <code>min_select</code> / <code>max_select</code>, permissions, and unknown options, then grants all rewards of the chosen mini kit</li><li>Failed claims, redemptions, and purchases return a language key (for example <code>error.kit.already_claimed</code> or <code>error.cdk.exhausted</code>); failures are never silently swallowed</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};